/* =====================================================================
   BASIC COURSE — part 1 (lessons b1–b14). Text uses {{Mac||Windows}}.
   ===================================================================== */
const COURSE={};               // id -> lesson
const L=o=>{COURSE[o.id]=o};
const DEMO=(build,steps,o={})=>Object.assign({build,steps},o);

/* ---------- shared demo helpers ---------- */
const moveWin=(k,dx,dy)=>['fn',async p=>{const w=p.q(k);if(!w)return;const l=parseFloat(w.style.left),t=parseFloat(w.style.top);p.rip('','press & hold');await sleep(450);w.style.left=(l+dx)+'%';w.style.top=(t+dy)+'%';p.c.style.transition='left .55s,top .55s';p.cx+=dx;p.cy+=dy;p.setCur();await sleep(750);p.c.style.transition='';p.rip('','let go');await sleep(300)}];
const macClass=(add,rm)=>['fn',async p=>{if(rm)p.m.classList.remove(...rm.split(' '));if(add)p.m.classList.add(add)}];
const appendTo=(k,html)=>['fn',async p=>{const e=p.q(k);if(e)e.insertAdjacentHTML('beforeend',P(html))},300];
const kbScene=(o={})=>`<div class="kbscene">${o.noPaper?'':'<div class="paper" data-k="paper"></div>'}${kb(o)}</div>`;
const startOpen=()=>[['to','apple'],['click'],['cls','apple','pick'],['show','amenu',500]];
const startPick=k=>[['if','mac',[['to',k],['cls',k,'pick'],['click'],['hide','amenu'],['cls','apple','pick',false]]],['if','win',[['to','am-power'],['click'],['show','pwm'],['to',k],['cls',k,'pick'],['click'],['hide','pwm'],['hide','amenu'],['cls','apple','pick',false]]]];
const mbkParts=()=>`<div class="mbk"><div class="lid" data-k="p-screen"><i class="cam" data-k="p-cam"></i><div class="scr"></div></div><div class="base"><div class="spk l" data-k="p-spk"></div><div class="kbm" data-k="p-kb">${Array.from({length:70},(_,i)=>i===13?'<i class="pw" data-k="p-power"></i>':'<i></i>').join('')}</div><div class="spk r"></div><div class="tpm" data-k="p-tp"></div><i class="port" data-k="p-port"></i></div></div>`;
const loginLayer=(hidden)=>`<div class="layer login ${hidden?'off':''}" data-k="login"><div class="clock">4:00</div><div class="av">[initial]</div><div class="nm">[name]</div><div class="pw" data-k="pw"></div></div>`;
const blackLayer=(hidden)=>`<div class="layer black ${hidden?'off':''}" data-k="black"></div>`;
const animals=['Aardvark','Bear','Camel','Dolphin','Eagle','Falcon','Gazelle','Hedgehog','Iguana','Jellyfish','Kangaroo','Lion','Meerkat','Narwhal','Octopus','Panda','Quail','Rabbit','Seahorse','Tiger','Walrus','Zebra'];
const notesWin=(cls='',pos=[8,12,42,55])=>win('notesw','{{Notes||Sticky Notes}}',`<div style="padding:2cqw;font-size:1.7cqw;line-height:1.6;flex:1;background:{{#fff||#FFF7C2}}"><b>My list</b><br>• learn shortcuts<br>• draw a dream computer<br>• read a book</div>`,pos,cls);
const calcWin=(cls='off',pos=[60,12,22,52])=>win('calcw','{{||Calculator}}',`<div class="calc"><div class="scr">42</div>${['C','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+'].map((b,i)=>`<span class="${i%4===3?'o':''}">${b}</span>`).join('')}</div>`,pos,cls);
const teMenu=`{{||<div class="cmdbar" style="gap:2cqw"><span data-k="m-file">File</span><span>Edit</span><span>View</span></div>}}`;
const teWin=(body,o={})=>win('te',o.title||'{{Untitled||Untitled - Notepad}}',`${teMenu}<div style="flex:1;background:#fff;padding:2.4cqw 3cqw;font-size:1.9cqw;line-height:1.6" data-k="tebody">${body}</div>`,o.pos||[10,10,62,62],o.cls||'');
const dockPlus=['finder','launch','safari','mail','notes','calc','textedit','word','ppt','excel','settings','|','trash'];
const SAFARI_MENUS=['File','Edit','View','History','Bookmarks','Window','Help'];
const browserDesk=(inner)=>desk(inner,{app:'Safari',menus:SAFARI_MENUS,run:['finder','safari']});
const teDesk=(inner)=>desk(inner,{app:'TextEdit',menus:['File','Edit','Format','View','Window','Help'],dock:dockPlus,run:['finder','textedit']});

/* ============================== UNIT 1 ============================== */
L({id:'b1',t:'Meet your computer',goal:'Learn the parts of a computer, how to turn it on, and how to shut it down the right way.',warm:'click',
learn:[
 {h:'The parts of your computer',p:`<p>A computer has parts, just like a bicycle has wheels and pedals. Press <b>Watch how</b> to meet each part of a laptop.</p><ul><li><b>Screen</b>: shows pictures and words.</li><li><b>Camera</b>: the tiny dot above the screen, for video calls.</li><li><b>Keyboard</b>: for typing letters and numbers.</li><li><b>{{Trackpad||Touchpad}}</b>: the smooth square you touch to move the arrow. Some people use a <b>mouse</b> instead.</li><li><b>Power button</b>: {{the top-right key. It also reads your fingerprint.||usually at the top-right of the keyboard or on the side.}}</li><li><b>Speakers</b>: where the sound comes out.</li><li><b>Ports</b>: holes on the side for the charger and cables.</li></ul><div class="tipbox">{{<b>Got an iMac?</b> That's the big screen on a stand. The computer hides behind the screen, and the keyboard and mouse are separate.||<b>Got a desktop PC?</b> The computer is the big box (the "tower") next to the desk. The screen, keyboard and mouse plug into it.}}</div>`,
  demo:DEMO(mbkParts,[['cap','This is a laptop. Let\'s meet its parts!',900],['hl','p-screen',200],['tag','p-screen','Screen'],['cap','The <b>screen</b> shows you pictures and words.',1400],['unhl'],['untag'],['hl','p-cam',200],['tag','p-cam','Camera'],['cap','The <b>camera</b> is for video calls.',1400],['unhl'],['untag'],['hl','p-kb',200],['tag','p-kb','Keyboard','up'],['cap','The <b>keyboard</b> is for typing.',1400],['unhl'],['untag'],['hl','p-tp',200],['tag','p-tp','{{Trackpad||Touchpad}}','up'],['cap','The <b>{{trackpad||touchpad}}</b> moves the arrow on the screen.',1400],['unhl'],['untag'],['hl','p-power',200],['tag','p-power','Power button','up'],['cap','The <b>power button</b> turns it on.',1400],['unhl'],['untag'],['hl','p-spk',200],['tag','p-spk','Speakers'],['cap','Sound comes out of the <b>speakers</b>.',1400],['unhl'],['untag'],['hl','p-port',200],['tag','p-port','Port for the charger'],['cap','The <b>ports</b> are for the charger and cables.',1500],['unhl'],['untag'],['cap','Now you know the parts of a computer!']],{cls:'plain',noCursor:true,intro:'A laptop, ready to meet you.',alt:'Drawing of a laptop with each part labelled one by one'})},
 {h:'Turn it on and log in',p:`<p>1. Press the <b>power button</b>.</p><p>2. Wait for the login screen. {{Click your name if you see more than one.||Click or press any key to wake it up. Click your name if you see more than one.}}</p><p>3. Type your {{password||PIN or password}}. It shows as dots so nobody can peek.</p><p>4. Press <kbd>return</kbd>. Your desktop appears!</p>`,
  demo:DEMO(()=>desk('',{icons:[['d1','My Work','folder',86,10]]})+loginLayer()+blackLayer(),[['curs','none'],['cap','The computer is off. Press the power button.',1100],['keys',['⏻'],1000],['hide','black',1000],['curs','arrow'],['cap','The login screen appears.',1000],['to','pw'],['click'],['cap','Type your {{password||PIN}}. It shows as dots.',600],['type','pw','••••••',140],['cap','Press {{return||Enter}}.',500],['keys',['return'],900],['hide','login',800],['cap','Welcome to your desktop!']],{start:[50,72]})},
 {h:'Shut down the right way',p:`<p>When you finish for the day, don't just close the lid or pull out the plug. Shut down properly:</p>{{<p>1. Click the little <b>apple</b> in the top-left corner of the screen.</p><p>2. Click <b>Shut Down…</b></p><p>3. Click the blue <b>Shut Down</b> button. Wait until the screen goes black.</p>||<p>1. Click the <b>Start</b> button (the four blue squares) at the bottom of the screen.</p><p>2. Click the <b>power</b> button ⏻ in the bottom corner of the Start menu.</p><p>3. Click <b>Shut down</b>. Wait until the screen goes black.</p>}}<div class="tipbox"><b>Short break?</b> Closing the lid of a laptop makes it sleep. That's fine for a snack break.</div>`,
  demo:DEMO(()=>desk('',{icons:[['d1','My Work','folder',86,10]]})+appleMenu()+dlg('sd','Are you sure you want to shut down your computer now?','',[['sd-c','Cancel'],['sd-ok','Shut Down','pri']])+blackLayer(true),[['cap','{{Click the apple in the top-left corner.||Click the Start button.}}',600],...startOpen(),['cap','{{A menu opens. Click <b>Shut Down…</b>||Click the power button, then <b>Shut down</b>.}}',600],...startPick('am-shut'),['if','mac',[['show','sd'],['cap','Click the blue <b>Shut Down</b> button.',600],['to','sd-ok'],['click'],['hide','sd']]],['show','black',1200],['cap','The computer is off. Well done!']],{start:[40,50]})}
],
mac:['Point to each part of your computer and say its name out loud.','Turn your computer on and log in.','{{Find the little apple in the top-left corner of the screen.||Find the Start button (four blue squares) at the bottom of the screen.}}','Shut down the right way, then turn it on again.'],
practice:[{type:'quiz',title:'Parts quiz',qs:[
 {q:'Which part do you use to type letters?',a:['The keyboard','The {{trackpad||touchpad}}','The speakers'],c:0,why:'The keyboard has a key for every letter.'},
 {q:'What is the best way to turn the computer off at the end of the day?',a:['{{Apple menu → Shut Down…||Start → Power → Shut down}}','Pull out the charger','Close the lid and walk away'],c:0,why:'Shutting down properly saves everything safely first.'},
 {q:'What does the camera do?',a:['Lets you do video calls','Plays music','Charges the computer'],c:0,why:'The camera is the tiny dot above the screen.'},
 {q:'Why does your {{password||PIN}} show as dots?',a:['So nobody can peek at it','Because the computer is broken','Dots are faster'],c:0,why:'Passwords and PINs are secret, so the computer hides them.'},
 {q:'Where does the sound come out?',a:['The speakers','The ports','The camera'],c:0}]}],
challenge:'Draw your computer on paper and label 6 parts. Then shut down and start up all by yourself.',
tell:'Show Mum or Dad how to shut down the right way, and name 5 parts of the computer.'});

const deskD2=(extra='')=>desk(extra+tpInset(),{icons:[['f1','Holiday','folder',12,16],['doc1','My story','doc',28,18]]});
L({id:'b2',t:'{{Trackpad||Touchpad}} & mouse master',goal:'Learn to click, double-click, right-click, drag and scroll.',warm:'click',
learn:[
 {h:'Click',p:`<p>Move one finger on the {{trackpad||touchpad}} to move the arrow. To <b>click</b>, {{press down with one finger until you feel a little "click"||tap once with one finger, or press the bottom-left of the touchpad}}.</p><p>With a mouse, press the <b>left</b> button once.</p><p>One click <b>selects</b> something. It turns blue.</p>`,
  demo:DEMO(()=>deskD2(),[['cap','Slide one finger to move the arrow…',500],['to','doc1'],['cap','…then click once.',300],['cls','tp','tap'],['click'],['cls','doc1','sel'],['cls','tp','tap',false],['cap','One click selects it. It turns blue!']],{start:[55,55]})},
 {h:'Double-click',p:`<p>Click <b>two times, very fast</b>, without moving. This <b>opens</b> things like folders and apps.</p><p>If nothing happens, you were too slow. Try again a little faster!</p>`,
  demo:DEMO(()=>deskD2(win('fw','Holiday',finderBody([['p1','Beach','pic'],['p2','Camel ride','pic'],['p3','Desert','pic']],'Recents'),[30,10,50,58],'off')),[['to','f1'],['cap','Two fast clicks on the folder…',300],['cls','tp','dbl'],['dbl'],['cls','f1','sel'],['show','fw',600],['cls','tp','dbl',false],['cap','…and it opens! Now close it.',700],['to','fw-close'],['click'],['hide','fw'],['cls','f1','sel',false],['cap','Double-click opens. {{The red button||The ✕ button}} closes.']],{start:[55,55]})},
 {h:'Right-click',p:`<p>A <b>right-click</b> opens a small menu of extra choices.</p>{{<ul><li><b>Trackpad:</b> press down with <b>two fingers</b> together.</li><li><b>Or:</b> hold the <kbd>control</kbd> key and click.</li><li><b>Mouse:</b> press the right button.</li></ul>||<ul><li><b>Mouse:</b> press the <b>right</b> button.</li><li><b>Touchpad:</b> tap with <b>two fingers</b> together, or press the bottom-right corner.</li></ul>}}<p>Press <kbd>esc</kbd> or click somewhere else to close the menu.</p>`,
  demo:DEMO(()=>deskD2(menu('ctx',[['c1','{{New Folder||View}}'],'-',['c2','{{Get Info||Sort by}}'],['c3','{{Change Wallpaper…||Refresh}}'],'-',['c4','{{Show View Options||New}}']],58,40)),[['move',57,39],['cap','{{Press the trackpad with two fingers…||Tap the touchpad with two fingers (or press the right mouse button)…}}',300],['cls','tp','two'],['rclick'],['show','ctx',500],['cls','tp','two',false],['cap','A menu with extra choices pops up!',1400],['keys',['esc'],800],['hide','ctx'],['cap','Press {{esc||Esc}} to close it.']],{start:[50,60]})},
 {h:'Drag and drop',p:`<p><b>Drag</b> means moving something to a new place:</p><p>1. Point at it. 2. Press down and <b>keep holding</b>. 3. Move to the new place. 4. <b>Let go</b>.</p><p>{{On a trackpad, keep one finger pressed down and slide with another finger if you run out of room.||On a touchpad, double-tap and keep your finger down on the second tap, then slide. With a mouse, hold the left button while you move.}}</p>`,
  demo:DEMO(()=>deskD2(),[['cap','Let\'s put "My story" into the Holiday folder.',800],['cls','tp','hold'],['drag','doc1','f1',{gone:true}],['cls','tp','hold',false],['cap','Dropped inside the folder!']],{start:[55,55]})},
 {h:'Scroll',p:`<p>When a page is too long for the screen, <b>scroll</b> to see the rest.</p><p>Put <b>two fingers</b> on the {{trackpad||touchpad}} and slide them up or down. With a mouse, roll the little wheel.</p>`,
  demo:DEMO(()=>deskD2(win('sw','Animal list',`<div style="padding:1.5cqw 2cqw;font-size:1.7cqw;line-height:2;overflow:hidden;flex:1"><div data-k="scl" class="scrl">${animals.map(a=>`<div>${a}</div>`).join('')}</div></div>`,[18,8,44,74])),[['to','sw',0,5],['cap','Two fingers slide…',300],['cls','tp','scroll'],['style','scl',{transform:'translateY(-62%)'},1900],['cls','tp','scroll',false],['cap','…and the list moves up so you can read more!',900],['cls','tp','scroll'],['style','scl',{transform:'translateY(0)'},1900],['cls','tp','scroll',false],['cap','Slide the other way to go back to the top.']],{start:[50,50]})}
],
mac:['Click on a desktop icon once. It turns blue (selected).','Double-click a folder to open it. Close it with {{the red button||the ✕ button}}.','Right-click on the desktop. Look at the menu, then press {{esc||Esc}}.','Drag a file into a folder and let go.','Open a long web page with a grown-up and scroll up and down.'],
practice:[{type:'click',goal:20},{type:'drag',title:'Fruit basket',intro:'Drag each fruit into the basket and each toy into the toy box. Press, hold, move, let go!',bins:[{id:'f',t:'Fruit basket'},{id:'t',t:'Toy box'}],items:[{t:'Apple',bin:'f'},{t:'Banana',bin:'f'},{t:'Mango',bin:'f'},{t:'Grapes',bin:'f'},{t:'Teddy bear',bin:'t'},{t:'Ball',bin:'t'},{t:'Kite',bin:'t'},{t:'Yo-yo',bin:'t'}]},{type:'scroll'}],
challenge:'Pop 20 bubbles in the Bubble pop game with no "Oops!". Then find the Flamingo as fast as you can.',
tell:'Show the difference between click, double-click and right-click.'});

L({id:'b3',t:'Keyboard tour',goal:'Find the important keys: letters, numbers, shift, space, {{return||Enter}}, {{delete||Backspace}} and the special keys.',warm:'click',
learn:[
 {h:'Letters and numbers',p:`<p>Every letter has its own key. Press a key once and the letter appears where the <b>blinking line</b> is.</p><p>The numbers are in the row above the letters.</p><div class="tipbox"><b>Hold a key down</b> and it repeats: aaaaaa! So press quickly and let go.</div>`,
  demo:DEMO(()=>kbScene(),[['cap','Press H, then I…',300],['press',['h','i'],'paper',420],['press',['space'],'paper'],['cap','Numbers are in the row above the letters.',300],['press',['1','2','3'],'paper',420],['cap','Each key makes one letter or number.']],{cls:'plain',noCursor:true,intro:'A keyboard and a piece of paper.'})},
 {h:'Shift and caps lock',p:`<p><b>Capital letter:</b> hold <kbd>shift</kbd> down, press the letter, then let go.</p><p><b>Symbols:</b> hold <kbd>shift</kbd> and press a number key to get the symbol on top. <kbd>shift</kbd> + <kbd>1</kbd> makes <b>!</b></p><p><kbd>caps lock</kbd> makes EVERYTHING CAPITALS. {{A green light shows it's on.||Many keyboards show a small light when it's on.}} Press it again to turn it off.</p>`,
  demo:DEMO(()=>kbScene(),[['cap','Hold shift and press H: a capital H!',300],['hold','shift'],['press',['h'],'paper',500,true],['hold','shift',false],['press',['e','l','l','o'],'paper',260],['cap','Hold shift and press 1 to get !',300],['hold','shift'],['press',['1'],null,500],['type','paper','!',10],['hold','shift',false],['press',['space'],'paper'],['cap','Caps lock ON.',300],['press',['caps']],['cls','key-capslock','onl'],['press',['h','i'],'paper',300,true],['cap','Press caps lock again to turn it OFF.',300],['press',['caps']],['cls','key-capslock','onl',false]],{cls:'plain',noCursor:true})},
 {h:'Space, {{return||Enter}} and {{delete||Backspace}}',p:`<p><kbd>space</kbd>: the long bar at the bottom. It makes a gap between words.</p><p><kbd>return</kbd>: starts a new line.</p><p><kbd>delete</kbd>: rubs out the letter just <b>before</b> the blinking line. Great for fixing mistakes!</p>`,
  demo:DEMO(()=>kbScene(),[['press',['m','y'],'paper',260],['cap','Space makes a gap.',300],['press',['space'],'paper',500],['press',['c','a','x'],'paper',260],['cap','Oops, "cax"! {{Delete||Backspace}} rubs out the last letter.',400],['press',['delete'],'paper',600],['press',['t'],'paper',400],['cap','{{Return||Enter}} starts a new line.',300],['press',['return'],'paper',500],['press',['h','i'],'paper',260],['cap','Fixed and on a new line!']],{cls:'plain',noCursor:true})},
 {h:'The special keys',p:`{{<ul><li><kbd>⌘ command</kbd>: the most important Mac key. You use it for shortcuts.</li><li><kbd>⌥ option</kbd> and <kbd>⌃ control</kbd>: helper keys for shortcuts.</li><li><kbd>esc</kbd>: "escape". It closes menus and stops things.</li><li><b>Arrow keys</b>: move the blinking line left, right, up and down.</li><li><kbd>tab</kbd>: jumps to the next box.</li></ul>||<ul><li><kbd>Ctrl</kbd>: the most important key for shortcuts.</li><li><kbd>⊞ Windows key</kbd>: opens the Start menu.</li><li><kbd>Alt</kbd>: a helper key for shortcuts.</li><li><kbd>Esc</kbd>: "escape". It closes menus and stops things.</li><li><b>Arrow keys</b>: move the blinking line left, right, up and down.</li><li><kbd>Tab</kbd>: jumps to the next box.</li></ul>}}`,
  demo:DEMO(()=>kbScene({noPaper:true}),[['hl','key-cmdl',200],['tag','key-cmdl','{{⌘ command||Ctrl}}: for shortcuts','up'],['cap','{{⌘ <b>command</b>: the most important Mac key!||<b>Ctrl</b>: the shortcut key!}}',1500],['unhl'],['untag'],['if','mac',[['hl','key-optl',200],['tag','key-optl','⌥ option','up'],['hl','key-ctrl',200],['tag','key-ctrl','⌃ control','up'],['cap','⌥ option and ⌃ control help with shortcuts.',1500]]],['if','win',[['hl','key-win',200],['tag','key-win','Windows key: Start','up'],['hl','key-optl',200],['tag','key-optl','Alt','up'],['cap','The Windows key opens Start. Alt helps with shortcuts.',1500]]],['unhl'],['untag'],['hl','key-esc',200],['tag','key-esc','{{esc||Esc}}: stop / close'],['cap','<b>{{esc||Esc}}</b> closes menus.',1400],['unhl'],['untag'],['hl','key-arrowleft',100],['hl','key-arrowup',100],['hl','key-arrowright',100],['tag','key-arrowup','Arrow keys','up'],['cap','Arrow keys move the blinking line.',1400],['unhl'],['untag'],['hl','key-tab',100],['tag','key-tab','{{tab||Tab}}','up'],['cap','<b>{{tab||Tab}}</b> jumps to the next box.',1400],['unhl'],['untag']],{cls:'plain',noCursor:true})}
],
mac:['{{Open TextEdit: press ⌘ + space, type textedit, press return. Click "New Document".||Open Notepad: press the ⊞ Windows key, type notepad, press Enter.}}','Type your first name with a capital letter at the start.','Press {{return||Enter}} and type the name of your favourite food.','Type a sentence that ends with ! (hold shift and press 1).','Make a mistake on purpose, then fix it with {{delete||Backspace}}.'],
practice:[{type:'keys'}],
challenge:'In {{TextEdit||Notepad}}, type this without help: <b>My name is [name] and I love computers!</b> Check every capital letter and the ! at the end.',
tell:'Show where the {{⌘ command||Ctrl}} key is, and show what {{delete||Backspace}} does.'});

