practice:[{type:'hot',title:'Browser detective',build:()=>browserDesk(browserWin('kiddle.co',searchPage(),{tab:'Kiddle'})),qs:[['Click the <b>address bar</b>.','addr'],['Click the <b>back</b> button.','back'],['Click the <b>reload</b> button.','reload'],['Click the button that opens a <b>new tab</b>.','newtab'],['Click the <b>star</b> that saves this page.','bm'],['Click the <b>browser</b> {{in the Dock||on the taskbar}}.','d-safari']]}],
