const resPage=(ad=true)=>`${ad?'<div class="res" data-k="ad"><a><span class="adtag">Ad</span>WIN a FREE tablet!!! Click now</a><small>prizes-4-u.example</small></div>':''}<div class="res" data-k="r1"><a>Arabian oryx – Kids encyclopedia facts</a><small>kids.kiddle.co</small><p>The Arabian oryx is the national animal of Oman, Qatar and Jordan...</p></div><div class="res" data-k="r2"><a>Arabian oryx | Zoo animal facts</a><small>zoo.example.org</small><p>Oryx can smell rain from far away...</p></div>`;
L({id:'b12',t:'Smart searching',goal:'Find good answers with safe search, good keywords and fact checking.',warm:'typing',warmLevel:2,
learn:[
 {h:'Use a safe search',p:`<p><b>Kiddle</b> (kiddle.co) is a search engine made for kids. Adults can use Google or Bing with <b>SafeSearch</b> turned on.</p><p>Type what you want to find in the search box and press <kbd>return</kbd>.</p>`,
  demo:DEMO(()=>browserDesk(browserWin('kiddle.co',searchPage(),{tab:'Kiddle'})),[['to','sbox'],['click'],['cls','sbox','focus'],['cap','Type what you want to find.',300],['type','q','arabian oryx facts',80],['keys',['return'],800],['set','page',resPage(false),200],['cap','A list of results! Click the one you want.']],{start:[50,60]})},
 {h:'Choose good keywords',p:`<p><b>Keywords</b> are the few most important words.</p><p>Instead of: <i>"can you please tell me how tall the Burj Khalifa is"</i></p><p>Type: <b>Burj Khalifa height</b></p><p>Short and clear works best!</p>`,
  demo:DEMO(()=>browserDesk(browserWin('kiddle.co',searchPage(),{tab:'Kiddle'})),[['to','sbox'],['click'],['cls','sbox','focus'],['type','q','can you please tell me how tall the burj khalifa is',45],['cap','Too many words! Let\'s make it shorter.',900],['erase','q',51,18],['type','q','burj khalifa height',80],['cap','Just the important words: much better!']],{start:[50,60]})},
 {h:'Pick a good result',p:`<ul><li><b>Skip</b> anything marked <b>Ad</b> or <b>Sponsored</b>. Those are adverts.</li><li><b>Never</b> click things that say you won a prize. It's a trick.</li><li>Choose websites you can trust: encyclopedias, museums, zoos, government and well-known news sites.</li></ul>`,
  demo:DEMO(()=>browserDesk(browserWin('kiddle.co',resPage(),{tab:'arabian oryx facts'})),[['to','ad',-10],['cap','"WIN a FREE tablet"? That\'s an advert trick!',900],['cls','ad','nope',true,1200],['cap','Skip it. Choose a trusted website.',400],['to','r1',-10],['hl','r1',300],['click'],['unhl'],['cap','An encyclopedia: a good choice!']],{start:[50,60]})},
 {h:'Check facts twice',p:`<p>Anyone can write things on the internet, and some of it is wrong. So check important facts on <b>two different websites</b>.</p><p>Same answer on both? Great! Different answers? Ask a grown-up to help.</p>`,
  demo:DEMO(()=>desk(win('b1','',browserBody('kids.kiddle.co',`<div style="font-weight:700;font-size:1.8cqw">Burj Khalifa</div><p>Height: <b data-k="f1">828 metres</b></p>`,'Kiddle'),[3,6,46,60])+win('b2','',browserBody('visit-dubai.example',`<div style="font-weight:700;font-size:1.8cqw">Tallest building</div><p>It is <b data-k="f2">828 m</b> tall.</p>`,'Visit Dubai'),[51,18,46,60]),{app:'Safari',run:['finder','safari']}),[['cap','Website 1 says…',300],['hl','f1',1200],['cap','Website 2 says…',300],['hl','f2',1200],['cap','Both say 828 metres. We can trust it!']],{noCursor:true})}
],
mac:['Go to kiddle.co in your browser.','Search: arabian oryx facts','Find 3 facts and type them into {{TextEdit||Notepad}}.','Check one of your facts on a second website.'],
practice:[{type:'quiz',title:'Best search words',qs:[
 {q:'You want to know how fast a cheetah runs. Which search is best?',a:['cheetah speed','I really want to know about how fast a cheetah can run please','fast'],c:0,why:'Short keywords work best.'},
 {q:'A result says "Sponsored". What is it?',a:['An advert','The best answer','A game'],c:0,why:'Sponsored and Ad mean someone paid to show it.'},
 {q:'A pop-up says "You won a prize! Click here". What do you do?',a:['Close it and tell a grown-up','Click it quickly','Type your address'],c:0,why:'Prize pop-ups are tricks.'},
 {q:'Two websites give different answers. What should you do?',a:['Check a third trusted site or ask someone','Pick the funnier one','Give up'],c:0},
 {q:'Which search is made for kids?',a:['Kiddle','Any website','The {{Trash||Recycle Bin}}'],c:0}]}],
challenge:'Find the height of the Burj Khalifa on two different websites. Do they match? Write the answer and both website names.',
tell:'Show your 3 oryx facts and the websites where you found them.'});

L({id:'b13',t:'Online safety',goal:'Learn the golden rules that keep you safe and kind on the internet.',warm:'typing',warmLevel:2,
learn:[
 {h:'Keep your information private',p:`<p><b>Never</b> tell anyone online your:</p><ul><li>full name, home address or school</li><li>phone number or passwords</li><li>photos of yourself</li></ul><p>If someone asks, don't answer. Close it and <b>tell a grown-up</b>.</p>`,
  demo:DEMO(()=>desk(`<div class="chatb off" data-k="chat"><div style="display:flex;justify-content:space-between;font-weight:700"><span>Game chat</span><span data-k="chatx" style="padding:0 .6cqw">✕</span></div><div class="bubl off" data-k="m1">hi!! you're really good at this game</div><div class="bubl off" data-k="m2">what school do you go to? 😊</div><div class="warnb off" data-k="warn">STOP! That's private. Don't answer.</div></div>`),[['show','chat',500],['show','m1',1100],['show','m2',1300],['cap','A stranger is asking for private information…',1000],['show','warn',1300],['cap','Don\'t answer. Close the chat…',400],['to','chatx'],['click'],['hide','chat'],['cap','…and tell a grown-up straight away.']],{start:[40,50]})},
 {h:'Make strong passwords',p:`<p>A strong password is <b>long</b> and mixes words, numbers and symbols, like <b>PurpleCamel!Dances7</b> (don't use this one, it's just an example!).</p><p>Keep your passwords <b>secret</b>. Only share them with Mum or Dad.</p>`,
  demo:DEMO(()=>`<div class="pwmeter"><b>Make a password</b><div class="fld2" data-k="pwf"></div><div class="trk"><i data-k="pwbar"></i></div><b data-k="pwlab">&nbsp;</b></div>`,[['type','pwf','cat',180],['style','pwbar',{width:'18%',background:'#E0463E'}],['set','pwlab','Weak: too short and easy to guess',1500],['erase','pwf',3,80],['type','pwf','PurpleCamel!Dances7',85],['style','pwbar',{width:'100%',background:'#12966A'}],['set','pwlab','Strong! Long, with a symbol and a number',1500]],{cls:'plain',noCursor:true})},
 {h:'Pop-ups and tricks',p:`<p>Sometimes a box jumps up saying things like <b>"You won a prize!"</b> or <b>"Your computer has a virus, click here!"</b></p><p>These are <b>tricks</b>. Don't click the big button. Close the box with the <b>✕</b>, or ask a grown-up.</p>`,
  demo:DEMO(()=>browserDesk(browserWin('games.example','<p>Fun games for kids</p>')+`<div class="popup" data-k="pop"><span class="x" data-k="popx">✕</span>CONGRATULATIONS!<div class="big2">You WON a tablet!</div>Just type your address to get it<br><span class="cta" data-k="cta">CLAIM NOW</span></div>`),[['cap','A pop-up says you won a prize…',900],['to','cta',-2,-4],['cap','Wait! This is a trick.',600],['cls','cta','nope',true,1000],['cap','Don\'t click the big button. Close it with ✕',400],['to','popx'],['click'],['hide','pop'],['cap','Safe! Tell a grown-up if pop-ups keep coming.']],{start:[50,70]})},
 {h:'The golden safety rules',p:`<div class="recap"><div><b>Keep it private</b>No name, address, school, phone or photos.</div><div><b>Passwords are secret</b>Only share with Mum or Dad.</div><div><b>Stop and ask</b>Ask before downloading, installing or buying.</div><div><b>Strangers stay strangers</b>Never chat to or meet people you only know online.</div><div><b>Tell a grown-up</b>If something feels scary, strange or unkind, close it and tell.</div><div><b>Be kind online</b>Only write what you'd say to someone's face.</div></div>`}
],
mac:['With a grown-up, look at the safety settings together: {{Apple menu → System Settings → Screen Time||Start → Settings → Accounts → Family (Microsoft Family Safety)}}.','Make a poster of the 6 golden safety rules. Make the title big!','Save it in your School folder.'],
practice:[{type:'drag',title:'Safe or not safe?',intro:'Drag each card into the right box.',bins:[{id:'y',t:'Safe'},{id:'n',t:'Not safe'}],items:[
 {t:'Telling a stranger your school',bin:'n',why:'Your school is private information.'},{t:'Asking before downloading',bin:'y'},{t:'Clicking "You won a prize!"',bin:'n',why:'Prize pop-ups are tricks.'},{t:'Keeping your password secret',bin:'y'},{t:'Sending your photo to someone you met in a game',bin:'n',why:'Never send photos to strangers.'},{t:'Telling someone about a mean message',bin:'y'},{t:'Using a safe search',bin:'y'},{t:'Sharing your home address in a chat',bin:'n'}]}],
challenge:'Make up a strong password example using 3 words, a number and a symbol. (Not your real password!)',
tell:'Tell Mum or Dad the 6 golden safety rules without looking.'});

const mailWin=(o={})=>win('mw',o.title||'New Message',mailBody(o),o.pos||[14,6,70,74],o.cls||'');
const mailDesk=(inner)=>desk(inner,{app:'Mail',run:['finder','mail']});
L({id:'b14',t:'Email basics',goal:'Write, send, attach and reply to emails.',warm:'typing',warmLevel:2,
learn:[
 {h:'The parts of an email',p:`<p>An <b>email</b> is a letter that travels through the internet in seconds. Every email has:</p><ul><li><b>To:</b> the email address, like <b>name@example.com</b> (always with an @).</li><li><b>Subject:</b> a few words that say what it's about.</li><li><b>Message:</b> your letter.</li><li><b>Send</b> button: the paper plane.</li></ul>`,
  demo:DEMO(()=>mailDesk(mailWin({to:'grandma@example.com',subj:'Hello from [name]',body:'Hi Grandma,<br><br>I can use a computer now!<br><br>Love from [name]'})),[['hl','to',100],['tag','to','To: who gets it'],['cap','<b>To</b>: the email address (it has an @).',1500],['unhl'],['untag'],['hl','subj',100],['tag','subj','Subject: what it\'s about'],['cap','<b>Subject</b>: what it\'s about.',1500],['unhl'],['untag'],['hl','mbody',100],['cap','<b>Message</b>: your letter.',1500],['unhl'],['hl','send',100],['tag','send','Send'],['cap','The paper plane <b>sends</b> it.',1500],['unhl'],['untag']],{noCursor:true})},
 {h:'Write an email',p:`<p>1. Open <b>{{Mail||Outlook}}</b> (or Gmail) and click <b>New Message</b> (or New mail).</p><p>2. Type the address in <b>To</b>.</p><p>3. Type a <b>Subject</b>.</p><p>4. Write your message: start with a greeting ("Hi Grandma,"), write your news, end with a goodbye ("Love from [name]").</p>`,
  demo:DEMO(()=>mailDesk(mailWin()),[['to','to',-10],['click'],['type','to','grandma@example.com',60],['to','subj',-10],['click'],['type','subj','Hello from [name]',60],['to','mbody',-10,-2],['click'],['type','mbody','Hi Grandma,\n\nThis week I learned to type on the home row!\n\nLove from [name]',40],['cap','A lovely email, ready to send.']],{start:[50,70]})},
 {h:'Attach a file',p:`<p>Want to send a drawing or photo? Click the <b>paperclip</b>, choose the file, and click <b>{{Choose File||Open}}</b>. It appears in your email.</p><p>Or just drag the file from {{Finder||File Explorer}} into the message.</p>`,
  demo:DEMO(()=>mailDesk(mailWin({to:'grandma@example.com',subj:'My drawing',body:'Hi Grandma,<br>Here is my dream computer!<br>Love from [name]'})),[['cap','Click the paperclip.',300],['to','clip'],['click'],['cap','Choose your drawing…',700],appendTo('mbody',`<div class="attach"><span class="fic pic" style="width:3cqw;height:2.4cqw"></span>Dream computer.png</div>`),['cap','It\'s attached! Now press Send.',500],['to','send'],['click'],['hide','mw'],['cap','Whoosh, sent!']],{start:[50,70]})},
 {h:'Reply to an email',p:`<p>Open the email you got and click the <b>Reply</b> arrow. The address and subject fill in by themselves. Just write your message and send!</p><div class="tipbox"><b>Rule:</b> only email people you know. Never open emails or attachments from strangers.</div>`,
  demo:DEMO(()=>mailDesk(mailWin({title:'Well done!',to:'[name]',subj:'Well done!',body:'Dear [name],<br>I loved your drawing!<br>Grandpa'})),[['cap','Grandpa wrote back! Click Reply.',500],['to','replyb'],['click'],['set','mw-title','Re: Well done!'],['set','to','grandpa@example.com'],['set','subj','Re: Well done!'],['set','mbody',''],['cap','The address fills in by itself.',600],['to','mbody',-10,-2],['click'],['type','mbody','Thank you Grandpa! See you on Friday.\n[name]',45],['to','send'],['click'],['hide','mw'],['cap','Reply sent!']],{start:[50,70]})}
],
mac:['Open {{Mail||Outlook}} or Gmail (with a grown-up if it\'s their account).','Write an email to a relative or friend.','Attach a drawing or photo.','Check it, then click Send.'],
practice:[{type:'email'}],
challenge:'When someone replies, reply back to them all by yourself.',
tell:'Show the three parts of an email: To, Subject and Message.'});
